async function load(){try{const r=await fetch('/api/overview');if(!r.ok)throw new Error('API unavailable');const d=await r.json();document.querySelector('#task-count').textContent=d.tasks.length;document.querySelector('#integrity').textContent='Integrity status: '+(d.integrity?'manifest present':'not generated');document.querySelector('#task-list').innerHTML=d.tasks.map(t=>`<article class="task"><h3>${t.id} · ${t.module}</h3><p>${t.control?'Matched control':'Core task'}</p><p>Oracle verdict: <strong class="${t.expected_verdict==='valid'?'valid':''}">${t.expected_verdict}</strong></p></article>`).join('')}catch(e){document.querySelector('#task-list').textContent='Unable to load evidence: '+e.message}}load();
